%[text] Pull values from constants file
clc
clear
close all

c = get_constants() %[output:594b48c4]
% assuming, for the sake of analysis, heavy part
% of train is in the rear.
x = 120;
load_factor = -1;
N = 200;
%[text] Calculate loads and distances
if (load_factor == -1)
    train_load = c.TRAIN_LOAD_1;
else
    train_load = load_factor * c.TRAIN_LOAD_2;
end
%[text] Calculate reaction forces
function [reaction_a,reaction_b] = reaction_forces(train_distance,train_load)
    % given the start of the train is x m from the left,
    % return the reaction forces at each support.
    
    % this only concerns vertical forces, since no
    % horizontal load is applied.

    % constraints: 0 <= x <= length - length of train
    c = get_constants();
    
    
    train_moments_a = train_distance .* train_load;
    reaction_b = sum(train_moments_a) / c.LENGTH;
    reaction_a = sum(train_load) - reaction_b;
end
%[text] Create SFD and BMD
function [SFD,BMD] = Graph(x, train_distance, train_load, do_plot)
    c = get_constants();

    cumulative_distances = cumsum(train_distance(1:end-1)) + x;
    [reaction_a, reaction_b] = reaction_forces(cumulative_distances,train_load);

    % SFD
    SFD_forces = [reaction_a -train_load reaction_b];
    SFD_net_forces = cumsum(SFD_forces);
    force_distances = [0 cumulative_distances c.LENGTH];
    
    if do_plot == 1
        figure;
        stairs([0,force_distances],[0,SFD_net_forces]);
        title('Shear Force Diagram')
        xlabel('Distance from start (mm)')
        ylabel('Shear force (N)')
        hold on
        yline(0)
        hold off
    end

    SFD = [[0,force_distances];[0,SFD_net_forces]];

    % BMD
    
    distance_intervals = abs(force_distances(2:end) - force_distances(1:end-1));
    BMD_moments = SFD_net_forces(1:end-1) .* distance_intervals;
    BMD_net_moments = cumsum(BMD_moments);

    if do_plot == 1
        figure;
        plot(force_distances,[0,BMD_net_moments]);
        title('Bending Moment Diagram')
        xlabel('Distance from start (mm)')
        ylabel('Bending moment (Nmm)')
        hold on
        yline(0)
        hold off
    end

    BMD = [force_distances;[0,BMD_net_moments]];
end

[SFD, BMD] = Graph(x, c.TRAIN_DIM, train_load,0);
%[text] Create 3D variants in respect to x
Xs = linspace(0,240,N) %[output:2df1c56f]

set(0, 'DefaultFigureVisible', 'off');
[SFDs, BMDs] = arrayfun(@(x) Graph(x,c.TRAIN_DIM, train_load, 0), Xs, UniformOutput=false);
set(0, 'DefaultFigureVisible', 'on');

fig = figure(Name='BMD vs Train Position'); %[output:1ad6d85e]
ax = axes(fig); %[output:1ad6d85e]
cla reset; hold on; %[output:1ad6d85e]
for i=1:length(Xs)
    x_vec = BMDs{i}(1, :);
    y_vec = BMDs{i}(2, :);
    z_vec = repmat(Xs(i), size(x_vec));

    plot3(x_vec,z_vec,y_vec) %[output:1ad6d85e]
end
hold off %[output:1ad6d85e]

pan off; datacursormode off; rotate3d on; %[output:1ad6d85e]
axis padded; axis vis3d; grid on; %[output:1ad6d85e]
ax.OuterPosition = [0.05 0.05 0.9 0.88]; %[output:1ad6d85e]
view(ax, 20, 10); %[output:1ad6d85e]

title('BMD vs Train Position') %[output:1ad6d85e]
xlabel('Distance Along Bridge (mm)') %[output:1ad6d85e]
ylabel('Train Position (mm)') %[output:1ad6d85e]
zlabel('Bending Moment (Nmm)') %[output:1ad6d85e]


xlim(ax,[0 1200]); %[output:1ad6d85e]

